use std::path::{Path, PathBuf};

use gob_plan::catalog::ConfigSchema;
use gob_plan::check::compile_diagnostics_with;
use gob_plan::lower::{SourceError, lower_source};

use super::marker_text;
use crate::files::GenFile;

/// One pack whose GRL sources `gen std-rules` compiles to checked-in Rust modules.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PackTarget {
    /// The pack directory name under `packs/`.
    pub name: &'static str,
    /// Config schema (workspace-relative) the pack's `config.*` relations are typed from, if any.
    pub config_schema: Option<&'static str>,
}

impl PackTarget {
    /// Where the pack's GRL sources live, relative to the workspace root.
    pub fn source_dir(&self) -> String {
        format!("packs/{}/rules", self.name)
    }

    /// Where the pack's generated modules are written, relative to the workspace root.
    pub fn out_dir(&self) -> String {
        format!("packs/{}/generated", self.name)
    }
}

/// The std pack, compiled against the gob host with no side config schema.
pub const STD: PackTarget = PackTarget {
    name: "std",
    config_schema: None,
};
/// The crunk-core pack, compiled against the crunk host with `crunk.json` typing its config.
pub const CRUNK_CORE: PackTarget = PackTarget {
    name: "crunk-core",
    config_schema: Some("docs/schemas/crunk.json"),
};
/// Every pack `gen std-rules` emits, in output order.
pub const TARGETS: [PackTarget; 2] = [STD, CRUNK_CORE];

/// Why the std rule modules could not be generated.
#[derive(Debug, thiserror::Error)]
pub enum StdRulesError {
    /// A source directory or file could not be read.
    #[error("read {}: {source}", gob_path::Shown::with_home(path, None))]
    Io {
        /// The path.
        path: PathBuf,
        /// Underlying error.
        source: std::io::Error,
    },
    /// A source did not parse or lower.
    #[error("{path}: {source}")]
    Source {
        /// The source path, relative to the root.
        path: String,
        /// Why it failed.
        source: SourceError,
    },
    /// A rule does not type-check against the pack's config schema.
    #[error("{path}: {report}")]
    Config {
        /// The source path, relative to the root.
        path: String,
        /// The compiler's rendered report.
        report: String,
    },
    /// A pack's config schema could not be read or is not usable.
    #[error("config schema {path}: {reason}")]
    Schema {
        /// The schema path, relative to the root.
        path: String,
        /// Why it is unusable.
        reason: String,
    },
}

/// Loads the config schema at `rel` under `root`.
fn load_schema(root: &Path, rel: &str) -> Result<ConfigSchema, StdRulesError> {
    let bad = |reason: String| StdRulesError::Schema {
        path: rel.to_owned(),
        reason,
    };
    let text = std::fs::read_to_string(root.join(rel)).map_err(|e| bad(e.to_string()))?;
    let doc = serde_json::from_str(&text).map_err(|e| bad(e.to_string()))?;
    let schema = ConfigSchema::from_json(&doc);
    if schema.is_empty() {
        return Err(bad("types nothing".to_owned()));
    }
    Ok(schema)
}

/// The `.grl` files directly under `dir`, sorted by name; none when the directory is absent.
fn sources(dir: &Path) -> Result<Vec<PathBuf>, StdRulesError> {
    let io = |source| StdRulesError::Io {
        path: dir.to_path_buf(),
        source,
    };
    let entries = match std::fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(e) => return Err(io(e)),
    };
    let mut out = Vec::new();
    for entry in entries {
        let path = entry.map_err(io)?.path();
        if path.extension().is_some_and(|e| e == "grl") {
            out.push(path);
        }
    }
    out.sort();
    Ok(out)
}

/// One generated module per rule of each target pack, each led by the GEN001 marker.
///
/// A pack with a config schema has every source type-checked against it first.
///
/// # Errors
/// [`StdRulesError`] when a source cannot be read, parsed, type-checked or lowered.
pub fn generate(root: &Path) -> Result<Vec<GenFile>, StdRulesError> {
    let mut files = Vec::new();
    for target in TARGETS {
        files.extend(generate_pack(root, target)?);
    }
    tracing::debug!(files = files.len(), "generated pack rule modules");
    Ok(files)
}

/// The generated modules of one pack under `root`.
///
/// # Errors
/// [`StdRulesError`] when a source cannot be read, parsed, type-checked or lowered.
pub fn generate_pack(root: &Path, target: PackTarget) -> Result<Vec<GenFile>, StdRulesError> {
    let source_dir = target.source_dir();
    let out_dir = target.out_dir();
    let schema = target
        .config_schema
        .map(|rel| load_schema(root, rel))
        .transpose()?;
    let mut files = Vec::new();
    for path in sources(&root.join(&source_dir))? {
        let rel = format!(
            "{source_dir}/{}",
            path.file_name()
                .map_or_else(String::new, |n| gob_path::Shown::with_home(
                    std::path::Path::new(&n),
                    None
                )
                .to_string())
        );
        let text = std::fs::read_to_string(&path).map_err(|source| StdRulesError::Io {
            path: path.clone(),
            source,
        })?;
        if let Some(schema) = &schema {
            let errors = compile_diagnostics_with(&rel, &text, Some(schema))
                .iter()
                .any(|d| d.severity == gob_plan::check::Severity::Error);
            if errors {
                return Err(StdRulesError::Config {
                    path: rel.clone(),
                    report: gob_plan::check::compile_report_with(&rel, &text, Some(schema)),
                });
            }
        }
        let plans = lower_source(&rel, &text).map_err(|source| StdRulesError::Source {
            path: rel.clone(),
            source,
        })?;
        for plan in plans {
            let content = format!(
                "// {}\n{}",
                marker_text("std-rules"),
                gob_plan::codegen::generate(&plan)
            );
            files.push(GenFile {
                path: format!("{out_dir}/{}.rs", plan.rule().to_ascii_lowercase()),
                content,
            });
        }
    }
    tracing::debug!(
        pack = target.name,
        files = files.len(),
        "generated pack rule modules"
    );
    Ok(files)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::files::{Mode, apply};

    const RULE: &str = "rule STD001 \"std-demo\" {\n  lang typescript\n  severity error\n  find c: call where c.callee == \"danger\"\n  report c \"danger\"\n  explain \"\"\"\n    Danger.\n\n    ## Remedy\n    Do not.\n  \"\"\"\n}\n";

    fn root_in(target: PackTarget, source: &str) -> tempfile::TempDir {
        let dir = tempfile::tempdir().unwrap();
        let src = dir.path().join(target.source_dir());
        std::fs::create_dir_all(&src).unwrap();
        std::fs::write(src.join("STD001.grl"), source).unwrap();
        dir
    }

    fn root_with(source: &str) -> tempfile::TempDir {
        root_in(STD, source)
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate
    #[test]
    fn a_changed_source_is_reported_stale_by_check_mode() {
        let dir = root_with(RULE);
        let files = generate_pack(dir.path(), STD).unwrap();
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].path, "packs/std/generated/std001.rs");
        apply(dir.path(), &files, Mode::Write).unwrap();
        let clean = apply(
            dir.path(),
            &generate_pack(dir.path(), STD).unwrap(),
            Mode::Check,
        )
        .unwrap();
        assert_eq!(clean.differing, 0);
        assert_eq!(clean.marker_problems, 0);
        let edited = RULE.replace("danger", "peril");
        std::fs::write(dir.path().join(STD.source_dir()).join("STD001.grl"), edited).unwrap();
        let stale = apply(
            dir.path(),
            &generate_pack(dir.path(), STD).unwrap(),
            Mode::Check,
        )
        .unwrap();
        assert_eq!(
            stale.differing, 1,
            "GEN001 must flag the regenerated module"
        );
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate
    #[test]
    fn a_generated_module_forbids_unsafe_and_touches_no_ambient_effect() {
        let dir = root_with(RULE);
        let text = &generate_pack(dir.path(), STD).unwrap()[0].content;
        assert!(text.contains("#![forbid(unsafe_code)]"));
        for ambient in [
            "std::fs",
            "std::process",
            "std::net",
            "std::env",
            "unsafe {",
        ] {
            assert!(!text.contains(ambient), "ambient effect `{ambient}`");
        }
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate
    #[test]
    fn a_broken_source_fails_generation() {
        let dir = root_with("rule {");
        assert!(matches!(
            generate_pack(dir.path(), STD),
            Err(StdRulesError::Source { .. })
        ));
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate
    #[test]
    fn the_generated_tree_has_no_grants_in_the_model() {
        let model = include_str!("../../../../design/model.grmb");
        let node = model
            .split("node std_rules")
            .nth(1)
            .and_then(|rest| rest.split("\n}\n").next())
            .expect("node std_rules in design/model.grmb");
        assert!(node.contains("owns \"packs/std/generated/**\""));
        assert!(
            !node.contains("may "),
            "the generated std node must hold no grants"
        );
    }

    const SCHEMA: &str = r##"{"properties":{"invariants":{"type":"object","properties":{"forbid_imports":{"type":"array","items":{"$ref":"#/$defs/F"}}}}},"$defs":{"F":{"type":"object","properties":{"from":{"type":"string"},"to":{"type":"string"}}}}}"##;

    const CONFIG_RULE: &str = "rule CRUNK001 \"cfg-demo\" {\n  lang rust\n  reads config\n  find f: config.invariants.forbid_imports\n  report f \"x\" when f.COL == f.to\n  example fire \"\"\"\n    x\n  \"\"\"\n  example clean \"\"\"\n    y\n  \"\"\"\n  explain \"\"\"\n    e\n\n    ## Remedy\n    r\n  \"\"\"\n}\n";

    const TEST_TARGET: PackTarget = PackTarget {
        name: "crunk-core",
        config_schema: Some("schema.json"),
    };

    fn config_root(col: &str) -> tempfile::TempDir {
        let dir = root_in(TEST_TARGET, &CONFIG_RULE.replace("COL", col));
        std::fs::write(dir.path().join("schema.json"), SCHEMA).unwrap();
        dir
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate_pack
    #[test]
    fn a_pack_with_a_schema_emits_under_its_own_directory() {
        let dir = config_root("from");
        let files = generate_pack(dir.path(), TEST_TARGET).unwrap();
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].path, "packs/crunk-core/generated/crunk001.rs");
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate_pack
    #[test]
    fn a_column_the_schema_lacks_fails_generation() {
        let dir = config_root("frm");
        assert!(matches!(
            generate_pack(dir.path(), TEST_TARGET),
            Err(StdRulesError::Config { .. })
        ));
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate_pack
    #[test]
    fn a_missing_schema_is_an_error_not_a_silent_skip() {
        let dir = root_in(TEST_TARGET, CONFIG_RULE);
        assert!(matches!(
            generate_pack(dir.path(), TEST_TARGET),
            Err(StdRulesError::Schema { .. })
        ));
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate
    #[test]
    fn the_real_pack_targets_generate_from_the_workspace() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let files = generate(&root).unwrap();
        assert!(
            files
                .iter()
                .any(|f| f.path == "packs/std/generated/todo001.rs")
        );
    }
}
